#include "room_rules_internal.hpp"
namespace wot::room {
bool Rules::accepting()const{return state_.phase=="battle"&&state_.server_tick>=static_cast<std::int64_t>(state_.config.get("prebattle_seconds").numeric(10.)*30.)&&rule::null(state_.battle_result);}
void Rules::reset(){state_.pending_ammo=array();state_.pending_damage=array();projectiles_.clear();tombstones_.clear();statistics_.clear();interactions_.clear();team_visible_.clear();team_lit_deadlines_.clear();state_.player_spotted.clear();ever_spotted_.clear();pending_kill_events_.clear();fire_attackers_.clear();track_attackers_.clear();stun_attackers_.clear();last_shell_fire_.clear();piercing_runs_.clear();participants_.clear();environment_pushes_.clear();environment_push_sequences_.clear();environment_falls_.clear();environment_critical_totals_.clear();stack_totals_.clear();pending_launches_.clear();frozen_edges_.clear();failed_launches_.clear();pending_contacts_.clear();equipment_frontiers_.clear();equipment_ready_.clear();ram_frontiers_.clear();environment_frontiers_.clear();equipment_requests_.clear();repair_requests_.clear();ram_requests_.clear();landing_results_.clear();ram_fingerprints_.clear();for(auto&c:capture_)c=Capture{};human_profiles_.clear();human_poses_.clear();human_probes_.clear();human_probe_receipts_.clear();retired_human_probes_.clear();human_frontiers_.clear();human_episodes_.clear();human_contacts_.clear();human_probe_seq_=0;last_capture_tick_=-1;finishing_=false;state_.rules=object();state_.rules.object["bases"]=object();for(int team=1;team<=2;++team){Value b=object();b.object["points"]=integer(0);b.object["invaders"]=integer(0);b.object["stopped"]=boolean(false);b.object["time_left"]=number(0.);state_.rules.object["bases"].object[std::to_string(team)]=std::move(b);}state_.battle_result={};}
Outcome Rules::dispatch(Sender sender,const Value&m){using namespace rule;const auto type=field(m,"type");const std::set<std::string> commands={"projectile_launch","projectile_progress","projectile_resolve","projectile_ricochet","track_repair","equipment_intent","player_environment","landing_observation","bot_ram_report","rules_state","battle_result","battle_receipt_ack","destructible","player_destructible_contact_result"};if(!commands.count(type))return {};
 try{require(isObject(m)&&finite(m),"message contains a non-finite value");if(type=="battle_receipt_ack"){require(!sender.worker,"receipt ACK requires player");auto*p=state_.actor("player",sender.id);require(p&&p->get("connected").truth(true),"unknown receipt owner");const auto id=field(m,"receipt_id"),account=field(*p,"account_key");require(!id.empty()&&id.size()<=96,"invalid receipt id");Value next=array();bool found=false;for(const auto&r:rows(receipts_)){if(field(r,"receipt_id")==id){require(field(r,"account_key")==account,"receipt account mismatch");found=true;}else next.array.push_back(r);}if(!found)return Outcome::reject("unknown_receipt");if(persist_&&!persist_(next))return Outcome::reject("persistence");receipts_=std::move(next);Outcome outcome=Outcome::accept();const auto waiting=pendingReceipts(account);if(!rows(waiting).empty())outcome.replies.push_back(rows(waiting).front());return outcome;}
  require(rule::integer(m.get("round_id"),1,INT32_MAX)==state_.round_id,"round does not match");if(type.rfind("projectile_",0)==0){require(rule::integer(m.get("authority_epoch"),0,INT32_MAX)==state_.authority_epoch,"authority epoch does not match");if(!sender.worker){const auto*p=state_.actor("player",sender.id);require(p&&p->get("connected").truth(true)&&p->get("participating").truth(true),"inactive projectile authority");}Outcome o=type=="projectile_launch"?launch(sender,m):type=="projectile_progress"?progress(sender,m):terminal(sender,m,type=="projectile_ricochet");if(o.status==Outcome::Status::accepted&&type!="projectile_launch")retryOperations();return type=="projectile_launch"?launchOutcome(sender,m,std::move(o)):o;}
  if(type=="track_repair")return repair(sender,m);if(type=="equipment_intent")return equipment(sender,m);if(type=="player_environment")return environment(sender,m);if(type=="landing_observation")return landing(sender,m);if(type=="bot_ram_report")return ram(sender,m);
  if(type=="rules_state"){require(sender.worker&&accepting(),"rules require active worker");require(isObject(m.get("rules"))&&isObject(m.get("rules").get("bases")),"invalid rules state");Value bases=object();for(int team=1;team<=2;++team){const auto&raw=m.get("rules").get("bases").get(std::to_string(team));Value base=object();base.object["points"]=integer(std::clamp<std::int64_t>(intField(raw,"points"),0,100));base.object["invaders"]=integer(std::clamp<std::int64_t>(intField(raw,"invaders"),0,30));base.object["time_left"]=number(std::max(0.,raw.get("time_left").numeric()));base.object["stopped"]=boolean(raw.get("stopped").truth());bases.object[std::to_string(team)]=std::move(base);}state_.rules.object["bases"]=std::move(bases);return Outcome::accept();}
  if(type=="battle_result"){require(sender.worker&&accepting(),"result requires active worker");const auto winner=rule::integer(m.get("winner"),0,2),base=has(m,"base_team")?rule::integer(m.get("base_team"),0,2):0;const auto reason=field(m,"reason");require(!reason.empty(),"battle result reason missing");return finish(static_cast<int>(winner),reason,static_cast<int>(base))?Outcome::accept():Outcome::reject("persistence");}
  if(type=="destructible"){require(sender.worker,"destruction requires worker");Value batch=array();batch.array.push_back(m);commitDestructibles(batch);retryOperations();return Outcome::accept();}
  if(type=="player_destructible_contact_result")return contactResult(sender,m);
 }catch(const std::exception&e){if(type=="projectile_launch"&&sender.worker&&field(m,"shooter_kind")=="bot"&&intField(m,"round_id",-1)==state_.round_id&&intField(m,"authority_epoch",-1)==state_.authority_epoch){const auto id=exactInteger(m.get("shooter_id")),seq=exactInteger(m.get("shot_seq"));if(m.get("shooter_id").resolved().kind==Kind::Integer&&m.get("shot_seq").resolved().kind==Kind::Integer&&id&&seq&&*id>0&&*id<=INT32_MAX&&*seq>0&&*seq<=INT32_MAX){const auto physical_id=projectileId(state_.round_id,"bot",*id,*seq);if(projectiles_.count(physical_id)||tombstones_.count(physical_id)||failed_launches_.count({*id,*seq}))return Outcome::reject("shape",e.what());failLaunch(*id,*seq,"launch_rejected");return Outcome::accept();}}return type=="projectile_launch"?launchOutcome(sender,m,Outcome::reject("shape",e.what())):Outcome::reject("shape",e.what());}return {};
}
void Rules::beginTick(){for(const auto&actors:{&state_.players,&state_.bots})for(const auto&kv:*actors){const ActorKey key{actors==&state_.bots?"bot":"player",kv.first};if(!participants_.count(key))participants_.emplace(key,kv.second);}if(!accepting())return;
 if(state_.server_tick>=static_cast<std::int64_t>((10.+state_.config.get("battle_duration_seconds").numeric(900.))*30.))finish(0,"battle_timeout");if(!rule::null(state_.battle_result))return;updateCapture();}
void Rules::advance(double dt,bool expire_stuns){if(!std::isfinite(dt)||dt<0.)throw std::invalid_argument("invalid room elapsed time");beginTick();if(!accepting())return;resolveHumanRams();advanceHazards(dt);std::vector<std::string> expired;for(const auto&p:projectiles_){if(rule::field(p.second.wire,"shooter_kind")=="bot")continue;if(state_.server_time_ms>=intField(p.second.wire,"launch_server_time_ms")+intField(p.second.wire,"max_time_ms")+2000)expired.push_back(p.first);}for(const auto&id:expired)retire(id,"expired");retryOperations();maybeFinish();if(expire_stuns)expireStuns();}
}
